import { useNavigate } from 'react-router-dom';

function Welcome() {
    const navigate = useNavigate();
    return (
        <>
            <div className="box">
            <h1 style={{ color: 'white' }}>Calculator App</h1>
        </div><br />
        <button onClick={() => navigate('/calculator')} style={{
            display : 'block' ,
            margin : '20px auto' ,
            padding : '10px 20px ',
            fontSize : '16px' ,
            cursor : 'pointer'
        }}>Get started</button>
        </>
    
    );
}

export default Welcome;